insert into ajour_registrations (serial_number, registration_type, registration_status, project_name, category_group, category, category1, execution_date, registration_created_date, subject, imported_at)
select s.serial_number, s.registration_type, s.registration_status, s.project_name, s.category_group, s.category, s.category1, s.execution_date::date, s.registration_created_date, s.subject, now() from src s
where not exists (select 1 from ajour_registrations a where a.project_name = 'Heklureitur' and a.serial_number = s.serial_number);
